380	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
381	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
382	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
383	// 解析其父目录；父目录也无法解析时退回原路径。
384	func canonicalLedgerPath(abs string) string {
385		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
386			return resolved
387		}
388		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
389			return filepath.Join(resolved, filepath.Base(abs))
390		}
391		return abs
392	}
393	
394	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
395	// 任一不合法则返回 ErrInvalid 且不创建任何文件。
396	//
397	// “路径是否占用”与“创建账本”由内核一步原子完成（见 createExclusive）：
398	//   - 路径上已有正常账本、损坏或空的普通文件、目录：返回 ErrExists，
399	//     原内容逐字节不变；
400	//   - 账本文件位置上是符号链接时（无论链接指向文件还是目录、目标是否
401	//     存在）：返回 ErrExists，链接本身与其去向都不变，也不会顺着悬空
402	//     链接把目标文件创建出来；
403	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时创建照常成功。
404	//
405	// 因此多个进程同时初始化同一尚不存在的账本（包括一方经真实目录、
406	// 另一方经指向该目录的符号链接访问同一目标）时，恰好一个成功，
407	// 其余返回 ErrExists，磁盘上完整保留胜出方的初始余额，绝不覆盖历史。
408	// 已有句柄打开（或有在途操作）的路径同样拒绝初始化。
409	func CreateLedger(path string, init []BalanceInit) error {
410		if err := validateInitial(init); err != nil {
411			return err
412		}
413		abs, err := filepath.Abs(path)
414		if err != nil {
415			return ledgerError(ErrStorage, "resolve path: %v", err)
416		}
417	
418		openMu.Lock()
419		defer openMu.Unlock()
420	
421		// 注册表按规范路径索引（父目录符号链接解析到真实目录），与 Open 一致。
422		// 注意 canonicalLedgerPath 对悬空符号链接只解析到其父目录、basename
423		// 仍是链接名；而下面的发布操作刻意使用字面 abs 而非该解析结果，确保
424		// 账本位置本身是符号链接时由内核原子拒绝，绝不顺着链接创建目标。
425		if openRegistry[canonicalLedgerPath(abs)] != nil {
426			// 已有句柄打开（或有在途操作）的路径不能再初始化：即便文件恰好被
427			// 外部删除，也不能用一本新账顶替正在使用的账本。
428			return ledgerError(ErrExists, "ledger is already initialized in this process")
429		}
430	
431		// 账本是否存在、内容是否完好一律以磁盘的原子创建结果为准；
432		// CreateLedger 不预登记内存状态，首次 Open 必须实际读取并校验该文件。
433		state := &ledgerState{
434			Version:     ledgerVersion,
435			Initial:     make(map[balanceKey]int64, len(init)),
436			Balances:    make(map[balanceKey]int64, len(init)),
437			Settlements: []Record{},
438			Refunds:     []RefundRecord{},
439		}
440		for _, b := range init {
441			k := balanceKey{b.Account, b.Asset}
442			state.Initial[k] = b.Balance
443			state.Balances[k] = b.Balance
444		}
445		// 发布使用字面绝对路径：父目录中的符号链接照常解析（允许经目录软链接
446		// 在尚未占用的文件位置创建新账本），账本位置本身的符号链接则被
447		// link(2) 原子拒绝；占用竞争失败返回 ErrExists，写入故障返回
448		// ErrStorage，两种情况下路径上都不会留下半成品。
449		if err := createExclusive(abs, state); err != nil {
450			return err
451		}
452		// 不登记 openRegistry：尚未有任何句柄，首次 Open 必须以磁盘文件为准，
453		// 这样在初始化与首次打开之间删除、清空或篡改文件都会被如实发现。
454		return nil
455	}
456	
457	func validateInitial(init []BalanceInit) error {
458		seen := map[balanceKey]bool{}
459		for i, b := range init {
460			if b.Account == "" {
461				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
462			}
463			if b.Asset == "" {
464				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
465			}
466			if b.Balance < 0 {
467				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
468			}
469			k := balanceKey{b.Account, b.Asset}
470			if seen[k] {
471				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
472			}
473			seen[k] = true
474		}
475		return nil
476	}
477	
478	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
479	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
480	// 因此并发提交按同一本账本串行化。
481	type Ledger struct {
482		path string
483		reg  *registryEntry
484		open bool
485	}
486	
487	type registryEntry struct {
488		mu       sync.Mutex // 保护 state；整个批次串行持有
489		state    *ledgerState
490		holders  map[*Ledger]struct{} // 当前打开的句柄
491		ops      int                  // 正在执行的 Submit/Query 数（含已关闭句柄的在途操作）
492		failHook FailWriter           // 仅测试注入
493	}
494	
495	// alive 报告该注册表项是否仍须保留：至少还有一个打开的句柄，或一个
496	// （可能来自已关闭句柄的）在途操作。全为零时该项可被注销，此后的 Open
497	// 重新以磁盘文件为准。
498	// 调用方必须持有 openMu。
499	func (r *registryEntry) alive() bool {
500		return len(r.holders) > 0 || r.ops > 0
501	}
502	
503	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
504	// 调用方必须持有 openMu。
505	func tryEvict(path string, reg *registryEntry) {
506		if !reg.alive() && openRegistry[path] == reg {
507			delete(openRegistry, path)
508		}
509	}
510	
511	var (
512		openMu       sync.Mutex
513		openRegistry = map[string]*registryEntry{}
514	)
515	
516	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
517	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
518	func Open(path string) (*Ledger, error) {
519		abs, err := filepath.Abs(path)
520		if err != nil {
521			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
522		}
523		abs = canonicalLedgerPath(abs)
524	
525		openMu.Lock()
526		defer openMu.Unlock()
527	
528		if reg := openRegistry[abs]; reg != nil {
529			// 同进程已有句柄（或在途操作）承接该账本：共享当前完整状态，不重新读盘。
530			// 注册表项只在存在活动句柄/在途操作期间保留，因此走到这里时磁盘文件
531			// 的状态已不再权威——例如它可能正被一笔在途付款以原子写替换。
532			h := &Ledger{path: abs, reg: reg, open: true}
533			reg.holders[h] = struct{}{}
534			return h, nil
535		}
536	
537		data, err := os.ReadFile(abs)
538		if err != nil {
539			if errors.Is(err, os.ErrNotExist) {
540				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
541			}
542			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
543		}
544		if len(bytes.TrimSpace(data)) == 0 {
545			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
546		}
547		dec := json.NewDecoder(bytes.NewReader(data))
548		var rawDoc json.RawMessage
549		if err := dec.Decode(&rawDoc); err != nil {
550			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
551		}
552		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
553		if tok, err := dec.Token(); err != io.EOF {
554			if err == nil {
555				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
556			}
557			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
558		}
559		state, err := decodeState(rawDoc)
560		if err != nil {
561			return nil, err
562		}
563	
564		reg := &registryEntry{state: state, holders: map[*Ledger]struct{}{}}
565		h := &Ledger{path: abs, reg: reg, open: true}
566		reg.holders[h] = struct{}{}
567		openRegistry[abs] = reg
568		return h, nil
569	}
570	
571	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
572	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
573	// 从磁盘重新加载而丢失正在写入的状态。
574	func (l *Ledger) Close() error {
575		openMu.Lock()
576		defer openMu.Unlock()
577		if !l.open {
578			return nil
579		}
580		l.open = false
581		delete(l.reg.holders, l)
582		tryEvict(l.path, l.reg)
583		return nil
584	}
585	
586	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
587	func (l *Ledger) beginOp() error {
588		openMu.Lock()
589		defer openMu.Unlock()
590		if !l.open {
591			return ledgerError(ErrClosed, "ledger handle is closed")
592		}
593		l.reg.ops++
594		return nil
595	}
596	
597	func (l *Ledger) endOp() {
598		openMu.Lock()
599		defer openMu.Unlock()
600		l.reg.ops--
601		tryEvict(l.path, l.reg)
602	}
603	
604	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
605	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
606	// 拆成商和余数两部分即可在 int64 内精确完成。
607	func feeFor(amount int64, feeBps int) int64 {
608		hi := amount / 10000
609		lo := amount % 10000
610		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
611	}
612	
613	func validateIntent(it PaymentIntent) (int64, string, bool) {
614		if it.ID == "" {
615			return 0, reasonEmptyID, false
616		}
617		if it.Account == "" {
618			return 0, reasonEmptyAccount, false
619		}
620		if it.Asset == "" {
621			return 0, reasonEmptyAsset, false
622		}
623		if it.Amount == nil || *it.Amount <= 0 {
624			return 0, reasonBadAmount, false
625		}
626		return *it.Amount, "", true
627	}
628	
629	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
630	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
631	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
632	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
633		if len(limits) == 0 {
634			return nil, nil
635		}
636		out := make(map[balanceKey]int64, len(limits))
637		for i, l := range limits {
638			if l.Account == "" {
639				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
640			}
641			if l.Asset == "" {
642				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
643			}
644			if l.MaxCharged == nil {
645				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
646			}
647			if *l.MaxCharged < 0 {
648				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
649			}
650			k := balanceKey{l.Account, l.Asset}
651			if _, dup := out[k]; dup {
652				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
653			}
654			out[k] = *l.MaxCharged
655		}
656		return out, nil
657	}
658	
659	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
660	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
661	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
662	//
663	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
664	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
665	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
666	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
667	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
668		if err := l.beginOp(); err != nil {
669			return nil, err
670		}
671		defer l.endOp()
672		limits, err := validateBatch(batch)
673		if err != nil {
674			return nil, err
675		}
676	
677		l.reg.mu.Lock()
678		defer l.reg.mu.Unlock()
679	
680		results := runBatch(batch, limits, l.reg.state, l.persistCharge)
681		return &BatchResult{Results: results}, nil
682	}
683	
684	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
685	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
686	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
687	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
688	//     失败、重复、冲突不消耗序号；
689	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
690	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
691	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
692	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
693	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
694	//
695	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
696	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
697	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
698	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
699	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
700	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
701		if err := l.beginOp(); err != nil {
702			return nil, err
703		}
704		defer l.endOp()
705		limits, err := validateBatch(batch)
706		if err != nil {
707			return nil, err
708		}
709	
710		l.reg.mu.Lock()
711		defer l.reg.mu.Unlock()
712	
713		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
714		sim := cloneState(l.reg.state)
715		results := runBatch(batch, limits, sim, simulateCharge)
716		return &PreviewResult{DryRun: true, Results: results}, nil
717	}
718	
719	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
720	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
721	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
722		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
723			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
724		}
725		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
726		return validateLimits(batch.Limits)
727	}
728	
729	// chargeEffect 是一笔预计成功扣款的全部账本效果：扣哪个组合、扣多少、
730	// 留下什么结算记录。它由付款规则产生，本身尚未生效；是否生效、如何生效
731	// （真实落盘或预览模拟）由生效策略决定。
732	type chargeEffect struct {
733		key    balanceKey
734		total  int64
735		record Record
736	}
737	
738	// commitCharge 是扣款生效策略：把一笔预计成功的扣款应用到状态 st 上。
739	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
740	// 该项执行之前的余额与历史。
741	type commitCharge func(st *ledgerState, eff chargeEffect) error
742	
743	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
744	// 付款规则（judgeIntent）与扣款生效（commit）分离：规则只读取 st 与
745	// 本批次已用额度给出判定和预计扣款效果，不改动任何状态；生效策略决定
746	// 效果如何落地——真实提交先改内存再原子落盘、失败回滚并报告
747	// storage_error，预览只在副本上推进内存状态、绝不落盘。两种操作共用
748	// 同一份规则，因此逐项判定完全一致。调用方必须持有 reg.mu。
749	func runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, commit commitCharge) []ItemResult {
750		out := make([]ItemResult, 0, len(batch.Intents))
751	
752		// 本次批次内各组合已消耗的额度，从零开始，仅成功生效的扣款计入。
753		used := make(map[balanceKey]int64, len(limits))
754	
755		for i := range batch.Intents {
756			it := &batch.Intents[i]
757	
758			// 1. 规则判定：纯读取，不产生任何副作用。
759			res, charge := judgeIntent(it, batch.FeeBps, limits, used, st)
760			if charge == nil {
761				out = append(out, res)
762				continue
763			}
764	
765			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
766			//    该项报告 storage_error，不留记录、不占额度，后项继续处理。
767			if err := commit(st, *charge); err != nil {
768				res.Status = StatusStorage
769				res.Reason = err.Error()
770				out = append(out, res)
771				continue
772			}
773	
774			// 3. 只有成功生效的扣款才消耗本批次额度（预览同样如此）。
775			used[charge.key] += charge.total
776			cp := charge.record
777			res.Status = StatusSettled
778			res.Record = &cp
779			out = append(out, res)
780		}
781		return out
782	}
783	
784	// judgeIntent 按付款规则评估一项请求，只读取状态与额度用量，不产生副作用。
785	// 返回逐项结果；预计成功时结果只填编号，扣款效果以 chargeEffect 描述，
786	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功编号的
787	// 重复/冲突、状态、溢出、本批次限额（先于余额）、余额。
788	func judgeIntent(it *PaymentIntent, feeBps int, limits map[balanceKey]int64, used map[balanceKey]int64, st *ledgerState) (ItemResult, *chargeEffect) {
789		res := ItemResult{ID: it.ID}
790	
791		// 1. 参数校验。未通过的编号不占用去重资格。
792		amount, reason, ok := validateIntent(*it)
793		if !ok {
794			res.Status = StatusInvalid
795			res.Reason = reason
796			return res, nil
797		}
798	
799		// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
800		//    任一不同则编号冲突。两者都不再扣款、不改原记录。
801		//    本批次内先（预计）成功的同编号项也在此被看到。
802		if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
803			if sameRequest(rec, it, amount, feeBps) {
804				cp := rec
805				res.Status = StatusDuplicate
806				res.Reason = reasonDuplicate
807				res.Record = &cp
808			} else {
809				res.Status = StatusConflict
810				res.Reason = reasonConflict
811			}
812			return res, nil
813		}
814	
815		// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
816		if it.State != "" && it.State != "pending" {
817			res.Status = StatusState
818			res.Reason = reasonNotPending
819			return res, nil
820		}
821	
822		// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
823		fee := feeFor(amount, feeBps)
824		if fee > math.MaxInt64-amount {
825			res.Status = StatusInvalid
826			res.Reason = reasonOverflow
827			return res, nil
828		}
829		total := amount + fee
830	
831		key := balanceKey{it.Account, it.Asset}
832	
833		// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
834		//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
835		//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
836		if max, capped := limits[key]; capped {
837			if u := used[key]; total > max-u {
838				res.Status = StatusLimitExceeded
839				res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
840				return res, nil
841			}
842		}
843	
844		// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
845		if total > st.Balances[key] {
846			res.Status = StatusFunds
847			res.Reason = reasonFunds
848			return res, nil
849		}
850	
851		// 7. 预计成功：描述扣款效果（序号按当前历史长度连续递增）。
852		return res, &chargeEffect{
853			key:   key,
854			total: total,
855			record: Record{
856				ID:        it.ID,
857				Account:   it.Account,
858				Paymaster: it.Paymaster,
859				Asset:     it.Asset,
860				Amount:    amount,
861				Nonce:     it.Nonce,
862				FeeBps:    feeBps,
863				Fee:       fee,
864				Charged:   total,
865				Seq:       int64(len(st.Settlements)) + 1,
866			},
867		}
868	}
869	
870	// simulateCharge 是预览的生效策略：只在（副本）状态上推进余额与历史，
871	// 绝不触碰磁盘，因此不会失败，预览结果中也不会出现 storage_error。
872	func simulateCharge(st *ledgerState, eff chargeEffect) error {
873		st.Balances[eff.key] -= eff.total
874		st.Settlements = append(st.Settlements, eff.record)
875		return nil
876	}
877	
878	// persistCharge 是真实提交的生效策略：先在内存生效，再原子落盘；
879	// 落盘失败回滚该项（恢复余额与历史），并返回存储错误。
880	func (l *Ledger) persistCharge(st *ledgerState, eff chargeEffect) error {
881		rollback := stageOn(st, eff.key, st.Balances[eff.key]-eff.total, eff.record)
882		if err := l.persistLocked(); err != nil {
883			rollback()
884			return err
885		}
886		return nil
887	}
888	
889	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
890	func cloneState(st *ledgerState) *ledgerState {
891		cp := &ledgerState{
892			Version:     st.Version,
893			Initial:     make(map[balanceKey]int64, len(st.Initial)),
894			Balances:    make(map[balanceKey]int64, len(st.Balances)),
895			Settlements: append([]Record(nil), st.Settlements...),
896			Refunds:     append([]RefundRecord(nil), st.Refunds...),
897		}
898		for k, v := range st.Initial {
899			cp.Initial[k] = v
900		}
901		for k, v := range st.Balances {
902			cp.Balances[k] = v
903		}
904		return cp
905	}
906	
907	// findRecordIn 在给定结算历史中按编号查找成功记录。
908	func findRecordIn(records []Record, id string) (Record, bool) {
909		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
910		for _, r := range records {
911			if r.ID == id {
912				return r, true
913			}
914		}
915		return Record{}, false
916	}
917	
918	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
919	// 余额与记录长度）。
920	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
921		oldBal, hadKey := st.Balances[key]
922		oldLen := len(st.Settlements)
923		st.Balances[key] = newBal
924		st.Settlements = append(st.Settlements, rec)
925		return func() {
926			if hadKey {
927				st.Balances[key] = oldBal
928			} else {
929				delete(st.Balances, key)
930			}
931			st.Settlements = st.Settlements[:oldLen]
932		}
933	}
934	
935	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
936	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
937	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
938	func validateRefundRequest(req *RefundRequest) (string, bool) {
939		if req.ID == "" {
940			return reasonEmptyRefundID, false
941		}
942		if req.SettlementID == "" {
943			return reasonEmptySettlement, false
944		}
945		if req.Reason == "" {
946			return reasonEmptyReason, false
947		}
948		return "", true
949	}
950	
951	// refundEffect 是一笔预计成功退款的全部账本效果：退回哪个组合、退回多少、
952	// 留下什么退款记录。它由退款规则产生，本身尚未生效；是否生效、如何生效
953	// （真实落盘，失败则回滚）由生效策略决定。
954	type refundEffect struct {
955		key    balanceKey
956		amount int64
957		record RefundRecord
958	}
959	
960	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
961	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
962	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
963	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
964		res.Reason = rec.Reason
965		res.SettlementID = rec.SettlementID
966		res.Account = rec.Account
967		res.Asset = rec.Asset
968		res.Charged = rec.Charged
969		cp := rec
970		res.Record = &cp
971	}
972	
973	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
974	// 返回逐项结果；预计成功时结果只填编号，退款效果以 refundEffect 描述，
975	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
976	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
977	// 目标结算存在性、目标是否已被其他退款编号退回。
978	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *refundEffect) {
979		res := RefundResult{ID: req.ID}
980	
981		// 1. 参数校验。未通过的编号不占用退款资格。
982		if reason, ok := validateRefundRequest(req); !ok {
983			res.Status = StatusInvalid
984			res.Reason = reason
985			return res, nil
986		}
987	
988		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
989		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
990		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
991		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
992			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
993				res.Status = StatusDuplicate
994				attachRefundDetail(&res, prior)
995			} else {
996				res.Status = StatusConflict
997				res.Reason = reasonRefundConflict
998			}
999			return res, nil
1000		}
1001	
1002		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
1003		target, exists := findRecordIn(st.Settlements, req.SettlementID)
1004		if !exists {
1005			res.Status = StatusNotFound
1006			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
1007			return res, nil
1008		}
1009	
1010		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
1011		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
1012			res.Status = StatusAlreadyRefunded
1013			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1014			return res, nil
1015		}
1016	
1017		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1018		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1019		rec := RefundRecord{
1020			ID:           req.ID,
1021			SettlementID: target.ID,
1022			Reason:       req.Reason,
1023			Account:      target.Account,
1024			Asset:        target.Asset,
1025			Amount:       target.Amount,
1026			Fee:          target.Fee,
1027			Charged:      target.Charged,
1028			AfterSeq:     int64(len(st.Settlements)),
1029			Seq:          int64(len(st.Refunds)) + 1,
1030		}
1031		return res, &refundEffect{
1032			key:    balanceKey{target.Account, target.Asset},
1033			amount: target.Charged,
1034			record: rec,
1035		}
1036	}
1037	
1038	// commitRefund 是退款生效策略：把一笔预计成功的退款应用到状态 st 上。
1039	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
1040	// 该项执行之前的余额与退款历史。
1041	type commitRefund func(st *ledgerState, eff refundEffect) error
1042	
1043	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1044	// 退款规则（judgeRefund）与生效（commit）分离：规则只读取 st 给出判定和
1045	// 预计退款效果，不改动任何状态；生效策略决定效果如何落地——真实提交先改
1046	// 内存再原子落盘、失败回滚并报告 storage_error。保存失败时 commit 已回滚
1047	// 该项（余额与退款历史恢复原样），该项不占退款编号、不把原付款标成已退款，
1048	// 前项成功保留、后项继续处理。调用方必须持有 reg.mu。
1049	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitRefund) []RefundResult {
1050		out := make([]RefundResult, 0, len(batch.Refunds))
1051		for i := range batch.Refunds {
1052			req := &batch.Refunds[i]
1053	
1054			// 1. 规则判定：纯读取，不产生任何副作用。
1055			res, eff := judgeRefund(req, st)
1056			if eff == nil {
1057				out = append(out, res)
1058				continue
1059			}
1060	
1061			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1062			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1063			if err := commit(st, *eff); err != nil {
1064				res.Status = StatusStorage
1065				res.Reason = err.Error()
1066				out = append(out, res)
1067				continue
1068			}
1069	
1070			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1071			res.Status = StatusRefundSuccess
1072			attachRefundDetail(&res, eff.record)
1073			out = append(out, res)
1074		}
1075		return out
1076	}
1077	
1078	// persistRefund 是真实退款的生效策略：先在内存生效，再原子落盘；
1079	// 落盘失败回滚该项（恢复余额与退款历史），并返回存储错误。
1080	func (l *Ledger) persistRefund(st *ledgerState, eff refundEffect) error {
1081		rollback := stageRefundOn(st, eff.key, st.Balances[eff.key]+eff.amount, eff.record)
1082		if err := l.persistLocked(); err != nil {
1083			rollback()
1084			return err
1085		}
1086		return nil
1087	}
1088	
1089	// stageRefundOn 在指定状态上应用一笔退款（余额增加 + 退款记录追加），
1090	// 返回回滚函数（恢复该项执行前的余额与退款记录长度）。
1091	func stageRefundOn(st *ledgerState, key balanceKey, newBal int64, rec RefundRecord) func() {
1092		oldBal, hadKey := st.Balances[key]
1093		oldLen := len(st.Refunds)
1094		st.Balances[key] = newBal
1095		st.Refunds = append(st.Refunds, rec)
1096		return func() {
1097			if hadKey {
1098				st.Balances[key] = oldBal
1099			} else {
1100				delete(st.Balances, key)
1101			}
1102			st.Refunds = st.Refunds[:oldLen]
1103		}
1104	}
1105	
1106	// findRefundIn 在给定退款历史中按编号查找成功记录。
1107	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1108		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1109		for _, r := range refunds {
1110			if r.ID == id {
1111				return r, true
1112			}
1113		}
1114		return RefundRecord{}, false
1115	}
1116	
1117	// findRefundOfSettlementIn 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1118	func findRefundOfSettlementIn(refunds []RefundRecord, settlementID string) (RefundRecord, bool) {
1119		for _, r := range refunds {
1120			if r.SettlementID == settlementID {
1121				return r, true
1122			}
1123		}
1124		return RefundRecord{}, false
1125	}
1126	
1127	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
1128	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
1129	// 结果与输入逐项对应，空批次返回空结果。
1130	//
1131	// 语义：
1132	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
1133	//     及原退款记录（不再入账）；任一不同返回 conflict（即使新目标不存在也一样，
1134	//     不能退化成 not_found）。
1135	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
1136	//     该结算已被其他退款编号退回返回 already_refunded，不增加余额。
1137	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
1138	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
1139	//   - 失败申请（参数错误、目标不存在、已退款、冲突、存储错误）不占用退款编号，
1140	//     之后可修改原因或目标再提交。
1141	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
1142		if err := l.beginOp(); err != nil {
1143			return nil, err
1144		}
1145		defer l.endOp()
1146	
1147		l.reg.mu.Lock()
1148		defer l.reg.mu.Unlock()
1149	
1150		results := runRefundBatch(batch, l.reg.state, l.persistRefund)
1151		return &RefundBatchResult{Results: results}, nil
1152	}
1153	
1154	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1155	
1156	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1157	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1158		return r.Account == it.Account &&
1159			r.Paymaster == it.Paymaster &&
1160			r.Asset == it.Asset &&
1161			r.Amount == amount &&
1162			r.Nonce == it.Nonce &&
1163			r.FeeBps == feeBps
1164	}
1165	
1166	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1167	func (l *Ledger) Query() (*Snapshot, error) {
1168		if err := l.beginOp(); err != nil {
1169			return nil, err
1170		}
1171		defer l.endOp()
1172		l.reg.mu.Lock()
1173		defer l.reg.mu.Unlock()
1174	
1175		st := l.stateView()
1176		bals := make([]BalanceView, 0, len(st.Balances))
1177		for k, v := range st.Balances {
1178			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1179		}
1180		sortBalances(bals)
1181		recs := make([]Record, len(st.Settlements))
1182		copy(recs, st.Settlements)
1183		refunds := make([]RefundRecord, len(st.Refunds))
1184		copy(refunds, st.Refunds)
1185		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1186	}
1187	
1188	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1189	func (l *Ledger) Balance(account, asset string) (int64, error) {
1190		if err := l.beginOp(); err != nil {
1191			return 0, err
1192		}
1193		defer l.endOp()
1194		l.reg.mu.Lock()
1195		defer l.reg.mu.Unlock()
1196		return l.stateView().Balances[balanceKey{account, asset}], nil
1197	}
1198	
1199	func sortBalances(bals []BalanceView) {
1200		sort.Slice(bals, func(i, j int) bool {
1201			if bals[i].Account != bals[j].Account {
1202				return bals[i].Account < bals[j].Account
1203			}
1204			return bals[i].Asset < bals[j].Asset
1205		})
1206	}
1207	
1208	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1209	func (l *Ledger) persistLocked() error {
1210		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1211			return ledgerError(ErrStorage, "injected write failure")
1212		}
1213		return atomicWrite(l.path, l.stateView())
1214	}
1215	
1216	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1217	func SetFailHook(l *Ledger, fw FailWriter) {
1218		l.reg.failHook = fw
1219	}
1220

