1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"math"
7		"math/big"
8		"os"
9		"path/filepath"
10		"strconv"
11		"strings"
12		"sync"
13		"testing"
14	)
15	
16	// ---- 输入解析 ----
17	
18	func TestParseReconcileRequestValid(t *testing.T) {
19		raw := []byte(`{"entries":[
20		  {"kind":"payment","id":"p1","account":"aa","asset":"usdc","amount":10,"fee":3,"charged":13},
21		  {"kind":"refund","id":"r1","account":"aa","asset":"usdc","amount":10,"fee":3,"charged":13,"settlement_id":"p1"}
22		]}`)
23		entries, err := ParseReconcileRequest(raw)
24		if err != nil {
25			t.Fatalf("parse: %v", err)
26		}
27		if len(entries) != 2 {
28			t.Fatalf("got %d entries", len(entries))
29		}
30		if entries[0].Index != 0 || entries[0].Kind != "payment" || entries[0].Charged != 13 {
31			t.Fatalf("entry0=%+v", entries[0])
32		}
33		if entries[1].Kind != "refund" || entries[1].SettlementID != "p1" || entries[1].Index != 1 {
34			t.Fatalf("entry1=%+v", entries[1])
35		}
36	
37		// 边界值合法：amount/charged 为正、fee 为 0 或 MaxInt64。
38		raw = []byte(`{"entries":[{"kind":"payment","id":"p","account":"a","asset":"z","amount":1,"fee":9223372036854775807,"charged":9223372036854775807}]}`)
39		if _, err := ParseReconcileRequest(raw); err != nil {
40			t.Fatalf("boundary values: %v", err)
41		}
42	}
43	
44	func TestParseReconcileRequestInvalid(t *testing.T) {
45		bad := []string{
46			`{bad`,                    // 非法 JSON
47			`{}`,                      // 缺 entries
48			`{"entries":[]} trailing`, // 尾随内容
49			`{"entries":[{"kind":"transfer","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":1}]}`, // 未知 kind
50			`{"entries":[{"kind":"payment","id":"","account":"a","asset":"z","amount":1,"fee":0,"charged":1}]}`,   // 空 id
51			`{"entries":[{"kind":"payment","id":"x","account":"","asset":"z","amount":1,"fee":0,"charged":1}]}`,   // 空 account
52			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"","amount":1,"fee":0,"charged":1}]}`,   // 空 asset
53			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","fee":0,"charged":1}]}`,             // 缺 amount
54			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"charged":1}]}`,          // 缺 fee
55			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":0}]}`,              // 缺 charged
56			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":0,"fee":0,"charged":1}]}`,  // amount 非正
57			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":-1,"fee":0,"charged":1}]}`,
58			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":-1,"charged":1}]}`,                   // fee 负
59			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":0}]}`,                    // charged 非正
60			`{"entries":[{"kind":"refund","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":1}]}`,                     // 退款缺 settlement_id
61			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":"1","fee":0,"charged":1}]}`,                  // 字符串金额
62			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1.5,"fee":0,"charged":1}]}`,                  // 小数
63			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1e3,"fee":0,"charged":1}]}`,                  // 科学计数
64			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":true,"fee":0,"charged":1}]}`,                 // 布尔
65			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":null,"fee":0,"charged":1}]}`,                 // null
66			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":9223372036854775808,"fee":0,"charged":1}]}`,  // 上越界
67			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":-9223372036854775809}]}`, // 下越界
68			`{"entries":"x"}`, // 类型不符
69		}
70		for i, in := range bad {
71			if _, err := ParseReconcileRequest([]byte(in)); err == nil || KindOf(err) != ErrInvalid {
72				t.Fatalf("case %d must be invalid_parameter, got %v: %s", i, err, in)
73			}
74		}
