}

// TestReconcileFlowSameIDPaymentAndRefundGo 付款与退款同编号分别匹配（Go 入口）。
func TestReconcileFlowSameIDPaymentAndRefundGo(t *testing.T) {
	l, _ := reconLedger(t)
	entries := []FlowEntry{
		{Index: 0, Kind: "payment", ID: "r1", Account: "aa-1", Asset: "usdc", Amount: 1, Fee: 0, Charged: 1},
