1	package payflow
2	
3	import (
4		"reflect"
5		"runtime"
6		"sync"
7		"testing"
8	)
9	
10	// 本文件为“扣款前预览”（submit --dry-run / Ledger.Preview）补充交错使用下的
11	// 回归保障：同一进程中两个句柄指向同一本账本时，一个句柄正在提交付款批次
12	// （批次仍在逐项保存、账本互斥锁尚未释放），另一个句柄发起预览。预览必须等
13	// 该批次整批处理完毕，再依据“完整余额 + 完整成功历史”在副本上判断整份预览：
14	//   - 不能把尚在保存的付款当成已结算（不能读到批次中途的历史）；
15	//   - 不能拿批次中途的余额去跑整份预览（不能读到批次中途的余额）；
16	//   - 前项成功、后项保存失败是允许的完整状态：后项已回滚、不留成功记录，
17	//     预览不得把该失败项当成已结算记录，也不得继承它的 storage_error；
18	//   - 预览始终带 dry_run，不扣余额、不落盘、不预留任何编号与成功序号。
19	//
20	// 场景固定为：一个账户 aa、一种资产 usdc，初始余额 100，费率 0。
21	// 句柄 A 顺序真实提交 p1=60、p2=30；在 p2 的“保存点”用故障注入门把批次
22	// 停住（此时 p1 已完整落账、锁仍被 A 持有）。句柄 B 就在此刻发起预览，
23	// 依次放入与原请求完全相同的 p1、p2 与新编号 p3=15。随后放行 p2 的保存，
24	// 分别覆盖“两笔都成功”和“p1 成功、p2 保存失败”两种完整结局。
25	
26	// secondPersistGate 是仅用于测试的持久化故障注入：第 1 次持久化（p1）正常
27	// 通过，第 2 次持久化（p2 的保存点）先通知 reached，再阻塞到 release 关闭，
28	// 最后按 fail 决定本次保存成功还是失败。整个等待期间调用方仍持有账本互斥锁。
29	type secondPersistGate struct {
30		calls   int
31		reached chan struct{} // p2 保存点已进入（批次停在中途、锁仍持有）
32		release chan struct{} // 放行 p2 的保存
33		fail    bool          // 放行后是否让 p2 本次持久化失败
34	}
35	
36	func (g *secondPersistGate) FailNextPersist() bool {
37		g.calls++
38		if g.calls != 2 {
39			return false
40		}
41		close(g.reached)
42		<-g.release
43		return g.fail
44	}
45	
46	// assertRecord 断言结果携带的结算记录与期望逐字段一致（含编号、账户、付款方、
47	// 资产、金额、nonce、费率、手续费、扣款总额与成功序号）。
48	func assertRecord(t *testing.T, label string, got *Record, want Record) {
49		t.Helper()
50		if got == nil {
51			t.Fatalf("%s: missing record, want %+v", label, want)
52		}
53		if !reflect.DeepEqual(*got, want) {
54			t.Fatalf("%s:\n got %+v\nwant %+v", label, *got, want)
55		}
56	}
57	
58	// runPreviewDuringSaveInterleave 执行交错用例。failSecond=false 时 p1、p2 都
59	// 真实成功；failSecond=true 时 p1 成功、p2 在保存点失败（storage_error，回滚）。
60	func runPreviewDuringSaveInterleave(t *testing.T, failSecond bool) {
61		t.Helper()
62		const (
63			acct, asset = "aa", "usdc"
64			p1Amount    = int64(60)
65			p2Amount    = int64(30)
66			p3Amount    = int64(15)
67		)
